// Step 1: Format Memory Item Payload
const input = $input.first().json;

const userId = input.user_id;
const ingestionId = input.ingestion_id;
const title = input.title || 'Nueva Memoria';
const summary = input.summary || input.text || '';
const memoryType = input.memory_type || 'note';
const confidence = input.confidence || 0.95;

return [{
  json: {
    ...input,
    user_id: userId,
    ingestion_id: ingestionId,
    title: title,
    summary: summary,
    memory_type: memoryType,
    confidence: confidence
  }
}];

const req = $('Prepare Memory Payload').first().json;
const memId = $input.first().json.id;

return [{
  json: {
    ok: true,
    status: 'completed',
    correlation_id: req.correlation_id,
    data: {
      memory_id: memId,
      memory_type: req.memory_type,
      title: req.title
    }
  }
}];
